CREATE INDEX planet_osm_polygon_highway_area ON planet_osm_polygon USING GIST (way) WHERE highway IN ('pedestrian', 'footway', 'service', 'living_street', 'platform', 'services') OR railway = 'platform' OR aeroway IN ('runway', 'taxiway', 'helipad');
CREATE INDEX planet_osm_polygon_junction ON planet_osm_polygon USING GIST (way) WHERE junction = 'yes';
CREATE INDEX planet_osm_polygon_landcover_symbols ON planet_osm_polygon USING GIST (way) WHERE ("natural" IN ('mud', 'wetland', 'wood', 'beach', 'shoal', 'reef', 'scrub') OR landuse IN ('forest', 'salt_pond')) AND building IS NULL;
CREATE INDEX planet_osm_polygon_lowzoom_poi ON planet_osm_polygon USING GIST (way) WHERE aeroway = 'aerodrome' OR tourism IN ('alpine_hut', 'wilderness_hut');
CREATE INDEX planet_osm_polygon_man_made ON planet_osm_polygon USING GIST (way) WHERE man_made IN ('pier', 'breakwater', 'groyne', 'bridge');
CREATE INDEX planet_osm_polygon_marina ON planet_osm_polygon USING GIST (way) WHERE leisure = 'marina';
CREATE INDEX planet_osm_polygon_military ON planet_osm_polygon USING GIST (way) WHERE (landuse = 'military' OR military = 'danger_area') AND building IS NULL;
CREATE INDEX planet_osm_polygon_name_z6 ON planet_osm_polygon USING GIST (ST_PointOnSurface(way)) WHERE name IS NOT NULL AND way_area > 5980000;
CREATE INDEX planet_osm_polygon_nobuilding ON planet_osm_polygon USING GIST (way) WHERE building IS NULL;
CREATE INDEX planet_osm_polygon_protected_area ON planet_osm_polygon USING GIST (way) WHERE boundary IN ('aboriginal_lands', 'national_park', 'protected_area') OR leisure = 'nature_reserve';
CREATE INDEX planet_osm_polygon_roads_area_text ON planet_osm_polygon USING GIST (ST_PointOnSurface(way)) WHERE name IS NOT NULL AND (highway IN ('pedestrian', 'footway', 'service', 'living_street', 'platform') OR (railway = 'platform' AND (tags->'location' NOT IN ('underground') OR tags->'location' IS NULL) AND (tunnel NOT IN ('yes', 'building_passage', 'avalanche_protector') OR tunnel IS NULL) AND (covered != 'yes' OR covered IS NULL)));
CREATE INDEX planet_osm_polygon_station ON planet_osm_polygon USING GIST (way) WHERE railway IN ('station', 'halt', 'tram_stop', 'subway_entrance') OR aerialway = 'station';
